-- Pickups v2: the community's current Cape Town pickups replace the website list (matches src/content/hub.ts).

delete from pickup_spot where id in (seed_id('pickup', 'Rondebosch pickup|0'), seed_id('pickup', 'Rondebosch pickup|6'), seed_id('pickup', 'Pinelands pickup|3'), seed_id('pickup', 'Maties pickup|2'), seed_id('pickup', 'Maties pickup|6'), seed_id('pickup', 'UCT social|4'), seed_id('pickup', 'Muizenberg beach pickup|5'), seed_id('pickup', 'Muizenberg beach pickup|6'));
on conflict (id) do update set name = excluded.name, start_time = excluded.start_time, venue_text = excluded.venue_text, notes = excluded.notes, contact_name = excluded.contact_name;
